  Widget _buildVibrationSettingsGroup() {
    return _SettingsGroup(
      title: '震动设置',
      children: [
        _SettingsSwitch(
          label: '震动反馈',
          subtitle: '触摸和游戏操作时的震动反馈',
          value: _settings.vibrationEnabled,
          onChanged: (value) {
            if (value) {
              HapticFeedback.mediumImpact();
            }
            _updateSetting(_settings.copyWith(vibrationEnabled: value));
          },
        ),
      ],
    );
  }

  Widget _buildAIDifficultyGroup() {
    return _SettingsGroup(
      title: 'AI设置',
      children: [
        _SettingsSelector(
          label: '默认AI难度',
          subtitle: '新游戏的默认AI难度',
          options: const ['easy', 'medium', 'hard'],
          optionLabels: const {
            'easy': '简单',
            'medium': '中等',
            'hard': '困难',
          },
          value: _settings.difficulty,
          onChanged: (value) {
            _updateSetting(_settings.copyWith(difficulty: value));
          },
        ),
      ],
    );
  }

  Widget _buildThemeGroup() {
    return _SettingsGroup(
      title: '棋盘主题',
      children: [
        const ListTile(
          leading: Icon(Icons.brush_outlined),
          title: Text('现代东方棋艺'),
          subtitle: Text('一期默认主题；更多主题将在后续版本开放'),
        ),
        const Divider(),
        _SettingsSwitch(
          label: '动画效果',
          subtitle: '棋子移动和吃子动画',
          value: _displaySettings.animationEnabled,
          onChanged: (value) {
            setState(() {
              _displaySettings =
                  _displaySettings.copyWith(animationEnabled: value);
              _settings = _settings.copyWith(animationEnabled: value);
            });
            _saveSettings();
          },
        ),
        const Divider(),
        _SettingsSwitch(
          label: '粒子效果',
          subtitle: '吃子与胜负反馈中的装饰效果',
          value: _displaySettings.particleEnabled,
          onChanged: (value) {
            setState(() {
              _displaySettings =
                  _displaySettings.copyWith(particleEnabled: value);
              _settings = _settings.copyWith(particleEnabled: value);
            });
            _saveSettings();
          },
